<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class MaintenanceRequest extends Model {protected $fillable=['occupancy_id','property_id','tenant_id','landlord_id','category','priority','title','description','status','acknowledged_at','started_at','resolved_at','tenant_confirmed_at','closed_at','escalated_at']; protected function casts():array{return ['acknowledged_at'=>'datetime','started_at'=>'datetime','resolved_at'=>'datetime','tenant_confirmed_at'=>'datetime','closed_at'=>'datetime','escalated_at'=>'datetime'];} public function occupancy():BelongsTo{return $this->belongsTo(Occupancy::class);} public function property():BelongsTo{return $this->belongsTo(Property::class);} public function tenant():BelongsTo{return $this->belongsTo(User::class,'tenant_id');} public function landlord():BelongsTo{return $this->belongsTo(User::class,'landlord_id');} public function events():HasMany{return $this->hasMany(MaintenanceRequestEvent::class);} public function photos():HasMany{return $this->hasMany(MaintenanceRequestPhoto::class);} public function isOpen():bool{return $this->status !== 'closed';}}
